import Foundation

/// Learned "is this fix right?" model (logistic regression over 13 facts about a fix).
/// Generated by `tools/train learn` from real typo data. Don't edit by hand; retrain instead.
/// Facts, in order: slip cost, cost per letter, lead over runner-up, word frequency, fits left word, fits right word, length, candidates in reach, macOS knows it, capitalised, contraction, known stem + ending, two words glued.
enum FixGate {
    /// Bold fixes more of your messy words; Careful only fixes when it's very sure
    enum Mode: String { case bold, careful }
    static var mode: Mode = .bold
    static var threshold: Double { mode == .bold ? boldThreshold : carefulThreshold }
    static var forceOff = false   // training/testing: use the hand-written rules instead
    static var isTrained: Bool { !weights.isEmpty && !forceOff }

    static let boldThreshold = 0.73
    static let carefulThreshold = 0.82
    static let mean: [Double] = [0.624127, 0.108913, 2.648168, 7.980143, 1.598538, 1.454258, 6.752300, 3.543035, 0.244400, 0.033700, 0.005000, 0.432602, 0.070100]
    static let scale: [Double] = [0.317079, 0.068655, 0.778941, 1.253547, 1.493432, 1.496000, 2.899232, 1.833698, 0.429731, 0.180456, 0.070534, 1.751412, 0.255315]
    static let weights: [Double] = [-0.925542, -0.297407, 0.751754, 0.814580, 0.289437, 0.399524, 0.652917, 0.108952, -0.558870, -0.155255, 0.012275, -0.421266, -0.133827]
    static let bias = 2.713945

    /// Chance (0-1) that fixing to the best candidate is right
    static func probability(_ x: [Double]) -> Double {
        var z = bias
        for i in 0..<weights.count { z += weights[i] * (x[i] - mean[i]) / scale[i] }
        return 1 / (1 + exp(-z))
    }
}
